                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader amzt_xDistBuf;
float4 amzSample_xDistBuf(float2 uv) { return float4(amzt_xDistBuf.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader backdrop;
float4 amzSample_comp(float2 uv) { return float4(backdrop.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_xDistBuf(uv);if(tex==2) return amzSample_comp(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_thickness;
uniform float amzp_feather;
layout(color) uniform half4 amzp_excludeColor1;
uniform float amzp_threshold1;
layout(color) uniform half4 amzp_excludeColor2;
uniform float amzp_threshold2;
layout(color) uniform half4 amzp_excludeColor3;
uniform float amzp_threshold3;
        float2 encodeFloat(float v) {
             float2 enc = fract(float2(1.0, 255.0)*v);
            enc.x -= enc.y/255.0;
            return enc;
        }
        float decodeFloat(float2 v) {
            return dot(v,float2(1.0,1.0/255.0));
        }
        void amzRender() {
            float radius=amzp_thickness*1.0;
            int from = -amzIntMax(1,int(radius));
            int to = amzIntMax(1,int(radius));
            float2 imgSize = getTexSize((screen.zw/1.0));
            float px = (1.0/imgSize.x);
            float py = (1.0/imgSize.y);
            if( amzPass==0 ) {
                float nearestOutside = 16383.0;
                float nearestInside = 16383.0;
                for(int i=from; i<to; i++ ) {
                    float x = float(i);
                    float4 sample = amzTexture(0,float2(amzScreenNorm().s + x*(px/1.0),amzScreenNorm().t));
                    float xdistOut = sample.a > 0.0 ? abs(x) : radius*2.0;
                    float xdistIn = sample.a < 0.003 ? abs(x) : radius*2.0;
                    nearestOutside = min(nearestOutside,xdistOut);
                    nearestInside = min(nearestInside,xdistIn);
                }
                amzOutput = float4(encodeFloat(nearestOutside/16383.0),encodeFloat(nearestInside/16383.0));
            } else {
                float nearestOutside = 16383.0;
                float nearestInside = 16383.0;
                for(int i=from; i<to; i++ ) {
                    float y = float(i);
                    float4 sample = amzTexture(1,float2(amzScreenNorm().s,amzScreenNorm().t + y*(py/1.0)));
                    float xdistOut = decodeFloat(sample.rg) * 16383.0;
                    float xdistIn = decodeFloat(sample.ba) * 16383.0;
                    float ydist = abs(y);
                    float distOut = length(float2(xdistOut,ydist));
                    float distIn = length(float2(xdistIn,ydist));
                    nearestInside = min(nearestInside,distIn);
                    nearestOutside = min(nearestOutside,distOut);
                }
                float nearestMid = max(nearestInside, nearestOutside);
                float4 original = amzTexture(0,amzScreenNorm().st);
                float inAlpha = amzp_thickness > 0.0 ? smoothstep((1.0-1.5/amzp_thickness)*(1.0-amzp_feather),1.0,nearestInside/(amzp_thickness/1.0)): 1.0;
                    inAlpha = 1. - inAlpha;
                float3x3 rgb2yuv = float3x3(
                     0.299, 0.587, 0.114,
                    -0.14713, -0.28886, 0.436,
                     0.615, -0.51499, -0.10001
                );
                float3x3 yuv2rgb = float3x3(
                    1.0, 0.0, 1.13983,
                    1.0, -0.39465, -0.58060,
                    1.0, 2.03211, 0.0
                );
                float4 bg = amzTexture(2,amzScreenNorm());
                float3 bgyuv = bg.rgb * rgb2yuv;
                float3 fgyuv = original.rgb * rgb2yuv;
                float3 exclyuv1 = amzp_excludeColor1.rgb * rgb2yuv;
                float tt1 = smoothstep(0.0,amzp_threshold1,length(exclyuv1.yz - fgyuv.yz));
                float3 exclyuv2 = amzp_excludeColor2.rgb * rgb2yuv;
                float tt2 = smoothstep(0.0,amzp_threshold2,length(exclyuv2.yz - fgyuv.yz));
                float3 exclyuv3 = amzp_excludeColor3.rgb * rgb2yuv;
                float tt3 = smoothstep(0.0,amzp_threshold3,length(exclyuv3.yz - fgyuv.yz));
                float3 adj = float3(fgyuv.x, mix(fgyuv.yz,bgyuv.yz,inAlpha * original.a * tt1 * tt2 * tt3)) * yuv2rgb;
                amzOutput = float4(adj,original.a);
            }
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

